window.RP_SESSION={"id":"S-f27cdc5775f0","messages":[{"id":"RP-III-0079515","time":"2026-04-20T21:52:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"...\n...\n...","characters":[]},{"id":"RP-III-0079516","time":"2026-04-20T21:52:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"@햄 찌 @하일로 조바","characters":[]},{"id":"RP-III-0079517","time":"2026-04-20T21:52:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"악인이여, 특급 열차를 타라...!","characters":[]},{"id":"RP-III-0079518","time":"2026-04-20T21:52:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"후후","characters":["P-07a519db64cf"]},{"id":"RP-III-0079519","time":"2026-04-20T21:52:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"https://youtu.be/HWULn1qjKIM?si=KtucMlml1IvDpo1F","characters":[]},{"id":"RP-III-0079520","time":"2026-04-20T21:52:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"반갑습니다. 티아멧, 그리고 레디언트 렉시.","characters":[]},{"id":"RP-III-0079521","time":"2026-04-20T21:54:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"여러분들은 지금 한 마차에 올라타있습니다.\n\n아치형 목조 골조에 천막을 덧대 씌운 이 웨건은 길이 4m, 폭2m, 높이 2.6m의 중형 짐마차입니다.\n\n이 마차엔 여러분 외에도 4명의 인원이 탑승해있고, 그들은 흔들리는 마차에 조용히 몸을 맡긴 채 앉아 있습니다.","characters":[]},{"id":"RP-III-0079522","time":"2026-04-20T21:54:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"질문을 몇 가지 던져볼게요.\n\n티아멧님이 !코인 을 던져보시겠어요?\n\n앞면이라면 티아멧님에게,\n뒷면이라면 렉시님에게 질문토록 하겠습니다.\n\n@햄 찌","characters":[]},{"id":"RP-III-0079523","time":"2026-04-20T21:54:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"!코인","characters":["P-22fdf8486544"]},{"id":"RP-III-0079524","time":"2026-04-20T21:54:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"뒷면 (이) 나옵니다.","characters":[]},{"id":"RP-III-0079525","time":"2026-04-20T21:55:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"좋아요. 렉시!\n\n이 마차에 어쩌다 타게 되었는지 말씀해주시겠어요?","characters":[]},{"id":"RP-III-0079526","time":"2026-04-20T21:57:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"@하일로 조바 집중해요 집중! 멍하니 있다간 멀미가 찾아 올거라구요?","characters":[]},{"id":"RP-III-0079527","time":"2026-04-20T21:58:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":" 오랜만에 어디로든 여행을 떠나보고 싶었습니다","characters":["P-07a519db64cf"]},{"id":"RP-III-0079528","time":"2026-04-20T21:59:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"좋아요 좋아.\n\n누구든 답답한 일상의 굴레를 벗어나 일탈의 충동을 느끼는 법이죠.\n\n근데 때마침 그 동행자가 티아멧이었군요?\n\n티아멧, 어쩌다 레디언트와 이 마차에 동행하게 되었는지 말씀해보시겠어요?","characters":[]},{"id":"RP-III-0079529","time":"2026-04-20T21:59:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"@햄 찌","characters":[]},{"id":"RP-III-0079530","time":"2026-04-20T22:02:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"티아멧에게 여행이라는 단어는 익숙치 않습니다. 그녀에게 여행은 곧 일상이고, 삶입니다. 이런 삶을 사는 그녀에게 여행이라는 말이 어울리는지는 잘 모르겠네요. 여튼, 티아멧이 가진 길드를 잠시 벗어나고 싶은 마음이 레디언트와 맞아떨어진 거죠.","characters":["P-22fdf8486544"]},{"id":"RP-III-0079531","time":"2026-04-20T22:03:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그렇군요. 두 캐릭터의 관계가 다소 어색할거란 것 알고 있어요.\n\n하지만 가끔은 낯선 사람과의 동행이 더 설레이는 법일지도 모릅니다.","characters":[]},{"id":"RP-III-0079532","time":"2026-04-20T22:03:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"물론, 이 마차는.\n\n설레임과는 정반대의 무언가를 태우고 있을지도 모르지만요.","characters":[]},{"id":"RP-III-0079533","time":"2026-04-20T22:03:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"먼저 마차의 구조를 보여드릴게요.","characters":[]},{"id":"RP-III-0079534","time":"2026-04-20T22:04:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그리고, 여러분은 몇 번에 앉아 계셨는지 얘기해봅시다.","characters":[]},{"id":"RP-III-0079535","time":"2026-04-20T22:04:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"사진","characters":[]},{"id":"RP-III-0079536","time":"2026-04-20T22:05:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"티아멧은 3번에 앉아 있습니다.","characters":["P-22fdf8486544"]},{"id":"RP-III-0079537","time":"2026-04-20T22:05:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"끌리듯 그곳에 앉았네요.","characters":["P-22fdf8486544"]},{"id":"RP-III-0079538","time":"2026-04-20T22:05:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"렉시는요?","characters":[]},{"id":"RP-III-0079539","time":"2026-04-20T22:05:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"렉시는 그녀의 맞은편( 2번 ) 에 앉았습니다","characters":["P-07a519db64cf"]},{"id":"RP-III-0079540","time":"2026-04-20T22:06:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"사진","characters":[]},{"id":"RP-III-0079541","time":"2026-04-20T22:07:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"좋습니다.\n\n이 마차가 여정을 떠나온지 이틀 정도 지난 상태라고 할게요.\n\n여러분은 서먹서먹하지만 몇마디 농담도 주고받고, 평소 길드에 관해 어떻게 생각하는지 이야기를 주고받으며 어느 정도의 아이스브레이킹이 끝난 상태입니다.","characters":[]},{"id":"RP-III-0079542","time":"2026-04-20T22:07:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"또, 이 마차에는 몇몇 인물들이 타고 있습니다.","characters":[]},{"id":"RP-III-0079543","time":"2026-04-20T22:08:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"먼저, 자신을 '떠돌이 상인'이라고 소개했던 로웬 하르트는\n\n나이는 마흔 정도 되어버리는 중년 남성입니다.\n\n그는 말이 많지만 친절한 사내입니다.\n\n하지만, 마차가 이동하는 동안 여러분이 짐칸(6번)에 가까이 갈 때마다 신경쓰듯 '뭘 꺼내시게?' 하며 물어오곤 했습니다.","characters":[]},{"id":"RP-III-0079544","time":"2026-04-20T22:09:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그 다음, 나이가 지긋해보이는 드워프 남성은 자신을 '여행하는 마법사'라고 소개했습니다. 그는 말 수가 적고, 매우 점잖은 드워리입니다.\n\n여러분이 마차의 인원들과 이야기를 나눌때마다, '그래서 그랬군.' '호오, 그거였군.' 하며 종종 아는 척을 해오기도 했습니다.","characters":[]},{"id":"RP-III-0079545","time":"2026-04-20T22:09:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"세 번째 인물의 이름은 '카르도 벨트릭'이라는 하이에나 데미간 남성이었는데, 그는 자신을 '전직 용병'이라 소개했습니다.\n\n무뚝뚝하고, 경계심이 강한 카르도는 이틀의 여정동안 여러분과의 대화를 탐탁지 않아했습니다.","characters":[]},{"id":"RP-III-0079546","time":"2026-04-20T22:11:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그리고 마지막 네번째 인물의 이름은 마이라 셀린.\n그녀는 서른 초반의 인간 여성이었는데, 자신을 '그저 운이 좋아 이 마차에 탄 평민 출신'이라고 소개했습니다.\n\n당신, 혹은 누군가가 '운이 좋다뇨?' 라고 되물었을 때, '여행을 떠난다는건, 누군가에겐 기적같은 일이기도 하거든요...' 하며 불안해하는 모습을 보이기도 했습니다.","characters":[]},{"id":"RP-III-0079547","time":"2026-04-20T22:11:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"이 네 명의 인물, 그리고 당신과 당신의 동료는.\n\n'여행길'에 오른 이 마차에 타고 있습니다 ...","characters":[]},{"id":"RP-III-0079548","time":"2026-04-20T22:11:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"* 자유 RP 해주세요.","characters":[]},{"id":"RP-III-0079549","time":"2026-04-20T22:13:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"어으, 피곤해...\"\n\n기지개를 켜며 찌뿌둥한 몸을 풉니다. 이틀 내내 마차에 실려 있었으니 몸이 굳을 만도 하죠.","characters":["P-22fdf8486544"]},{"id":"RP-III-0079550","time":"2026-04-20T22:13:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 아따, 그래서 지가 그 아룡놈 대가리에 이 주먹을 빡!! \"\n\n 신나게 자신의 영웅담을 풀어놓는 렉시.. 이 얘기만 벌써 세 번쨉니다.","characters":["P-07a519db64cf"]},{"id":"RP-III-0079551","time":"2026-04-20T22:14:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 으핳핫, 이 친구야 그 얘기만 벌써 세 번째라구. 근데 세 번이나 들어도 질리지가 않는구만. \"\n\n로웬이 렉시의 얘기에 한 번 더 웃었습니다. 그리곤 피곤해하는 티아멧에게 얘기합니다.\n\n\" 한 숨 주무시는게 어떤가? 마차가 도착하려면 아직 하룻밤이나 더 가야하니까 말일세. \"","characters":[]},{"id":"RP-III-0079552","time":"2026-04-20T22:15:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 아, 맞아예~ 다크서클이 조바 도련님 급입니더- \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079553","time":"2026-04-20T22:15:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 맞아요, 아직 시간은 한참 남았으니까 눈 좀 붙이셔요. \"\n\n마이라 셀린 또한 얘기합니다.","characters":[]},{"id":"RP-III-0079554","time":"2026-04-20T22:16:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 도착하믄, 깨워드릴테니께 좀 주무시지예? \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079555","time":"2026-04-20T22:16:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"덜컹거리니까 편히 잘 수가 없단 말야...\"\n\n투구를 베고는 의자에 누워 봅니다.","characters":["P-22fdf8486544"]},{"id":"RP-III-0079556","time":"2026-04-20T22:16:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"좋아요 티아멧. 당신의 옆에는 누가 앉아 있었나요?","characters":[]},{"id":"RP-III-0079557","time":"2026-04-20T22:16:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"셀린이 앉아 있었습니다.","characters":["P-22fdf8486544"]},{"id":"RP-III-0079558","time":"2026-04-20T22:17:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"좋습니다. 렉시, 당신의 옆에는요?","characters":[]},{"id":"RP-III-0079559","time":"2026-04-20T22:19:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"@하일로 조바 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시?","characters":[]},{"id":"RP-III-0079560","time":"2026-04-20T22:19:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"카르도가 앉아 있습니다","characters":["P-07a519db64cf"]},{"id":"RP-III-0079561","time":"2026-04-20T22:20:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"사진","characters":[]},{"id":"RP-III-0079562","time":"2026-04-20T22:20:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"좋아요. 이 위치를 기억하도록 합시다.","characters":[]},{"id":"RP-III-0079563","time":"2026-04-20T22:22:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"덜컹거리는 마차.\n\n웨건 밖의 하늘은 촘촘히 박힌 별이 반짝이는 어둡고 깊은 밤입니다.\n\n마부석에 달린 횃대의 등불이 앞을 밝히고, 마차 내부에는 작은 등불 하나가 내부를 비추고 있습니다.","characters":[]},{"id":"RP-III-0079564","time":"2026-04-20T22:22:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 좀 심심하시면, 내 노래라도 한 곡 할까요? \"\n\n로웬이 얘기합니다.","characters":[]},{"id":"RP-III-0079565","time":"2026-04-20T22:23:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"잔잔한 곡으로 부탁해요.\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079566","time":"2026-04-20T22:23:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 아따, 행님! 노래 좀 치십니꺼? \"\n\n 렉시가 무릎을 탁ㅡ 치며 묻네요","characters":["P-07a519db64cf"]},{"id":"RP-III-0079567","time":"2026-04-20T22:24:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 좋습니다. 내 이곳 저곳 떠돌아다니며 물건을 팔면서 종종 벤조도 연주해먹고 살았거던요? 소싯적엔 여자들도 꽤나 홀렸죠. \"\n\n로웬은 등 뒤에 세워두었던 벤조를 꺼내 현을 조율하며 얘기했습니다.\n\n그 모습을 잠깐 쳐다본 카르도는 날카로운 송곳니를 드러내며 '쯧-' 하고 혀를 찼지만,\n\n기 센 로웬은 기죽지 않는 모양입니다.","characters":[]},{"id":"RP-III-0079568","time":"2026-04-20T22:25:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 우훠~ 로웬! 로웬! \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079569","time":"2026-04-20T22:25:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"이내 로웬 하르트의 연주가 시작되고, 그는 '나귀 탄 사나이' 를 천천히 노래했습니다.\n\n그의 노래 실력이 썩 좋지는 않았으나, 잔잔한 벤조 연주와 함께 낮은 중년 남성의 음성은 티아멧이 노곤노곤히 잠에 들기엔 적절해보였습니다.","characters":[]},{"id":"RP-III-0079570","time":"2026-04-20T22:26:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그리고 ... 그의 연주가 끝날 떄 즈음, 마차의 속도가 줄어들기 시작하더니 마부가 소리칩니다.\n\n\" 십 오분 쉬었다 가겠소-! 다들 소변들 뉘고 오시던지요. 클클클. \"","characters":[]},{"id":"RP-III-0079571","time":"2026-04-20T22:27:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"@햄 찌 @하일로 조바 10시 40분에 다시 모이는 걸로 합시다!","characters":[]},{"id":"RP-III-0079572","time":"2026-04-20T22:27:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"역시 방장 사마","characters":["P-07a519db64cf"]},{"id":"RP-III-0079573","time":"2026-04-20T22:27:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"넵","characters":["P-22fdf8486544"]},{"id":"RP-III-0079574","time":"2026-04-20T22:40:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"@하일로 조바 @햄 찌 좋습니다...! 복귀하신다면, 마차가 잠시 멈춰선 동안 두 분은 밖에서 어떤 행동을 했는지 설명해주시겠어요?","characters":[]},{"id":"RP-III-0079575","time":"2026-04-20T22:42:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"잠시 볼일도 보고, 스트레칭도 하고... 고속도로 휴게실에 들른 것과 다를 바 없는 시간을 보냈습니다. 소떡소떡은 없지만요.","characters":["P-22fdf8486544"]},{"id":"RP-III-0079576","time":"2026-04-20T22:42:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":" 빠르게 볼일을 본 후, 마차 앞에서 로웬과 함께 담배를 피며 수다를 떨고 있었습니다.","characters":["P-07a519db64cf"]},{"id":"RP-III-0079577","time":"2026-04-20T22:43:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"오호. 좋습니다.\n\n비록 소떡소떡은 없었지만 ...\n\n아마 로웬은 티아멧과 렉시에게 쪄온 감자도 나누며 잠깐의 담소를 나눴을 것 같습니다.","characters":[]},{"id":"RP-III-0079578","time":"2026-04-20T22:44:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"여러분이 다시 마차로 돌아가던 그 순간 ...\n\n\" 꺄아아악-!! \"\n\n여성의 비명소리가 들렸습니다.","characters":[]},{"id":"RP-III-0079579","time":"2026-04-20T22:44:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"https://youtu.be/rxK_IrcM5BY?si=BgMvBqTvawBpc7AQ","characters":[]},{"id":"RP-III-0079580","time":"2026-04-20T22:45:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 오메, 씨@불 뭔 소란이노? \"\n\n 그 소리에 깜짝 놀라며 소리가 난 곳을 쳐다봅니다","characters":["P-07a519db64cf"]},{"id":"RP-III-0079581","time":"2026-04-20T22:45:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"???\"\n\n놀란 채 빠르게 마차로 향합니다.","characters":["P-22fdf8486544"]},{"id":"RP-III-0079582","time":"2026-04-20T22:46:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"소리가 난 곳은 마차였습니다.\n\n그건 마이라의 비명이었습니다.\n\n로웬도, 카르도도, 그리고 여행하는 드워프 마법사도 마차를 쳐다보며 다가갔을 겁니다.\n\n다가 온 티아멧을 향해, 마이라가 얘기합니다.\n\n\" 마차에... 마차에 시체가 있어요...! \"","characters":[]},{"id":"RP-III-0079583","time":"2026-04-20T22:47:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 이게 뭔..! \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079584","time":"2026-04-20T22:47:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"어, 그게 무슨...\"\n\n시체? 누가 죽었단 말인가. 하지만 사람들은 모두 마차에서 내려 있었는데, 그러면 마부가...?","characters":["P-22fdf8486544"]},{"id":"RP-III-0079585","time":"2026-04-20T22:48:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":" 렉시는 그 시신이 살인으로 생긴 시체인지 알아보기 위해, 시신을 유심히 관찰해봅니다.","characters":["P-07a519db64cf"]},{"id":"RP-III-0079586","time":"2026-04-20T22:48:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 오 이럴수가. 마부가? 마부가 죽었습니까 여인? \"\n\n로웬이 식은땀을 흘리며 다가섭니다.\n\n좋습니다, 렉시! 지능 판정 해볼까요!?","characters":[]},{"id":"RP-III-0079587","time":"2026-04-20T22:49:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"!지능","characters":["P-07a519db64cf"]},{"id":"RP-III-0079588","time":"2026-04-20T22:49:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레디언트 렉시'의 지능 판정 :\n[2] + [-1] = [1]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-III-0079589","time":"2026-04-20T22:49:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"아 모르겠당","characters":["P-07a519db64cf"]},{"id":"RP-III-0079590","time":"2026-04-20T22:50:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"이런, 지금 당장은 발견할 수 있는 단서가 보이질 않습니다.\n\n마이라는 혼란스러운 듯 눈물을 흘리며 당신에게 다가와 옷자락을 잡습니다.\n\n\" 마부는 아니에요, 처음 보는 얼굴이에요...! 이럴수가, 전혀 모르는 사람이라구요...! \"","characters":[]},{"id":"RP-III-0079591","time":"2026-04-20T22:50:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"시체가 피를 흘리고 있나요?","characters":["P-22fdf8486544"]},{"id":"RP-III-0079592","time":"2026-04-20T22:51:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"네. 그렇습니다 티아멧. 시체는 마차 가운데에 엎드려 있는데, 피가 새어나온 것이 보입니다.","characters":[]},{"id":"RP-III-0079593","time":"2026-04-20T22:52:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"뭐야 대체...\"\n\n침착하게 시체 곁으로 다가가서는, 사인을 알아내기 위해 엎드려 있는 시체를 뒤집습니다.","characters":["P-22fdf8486544"]},{"id":"RP-III-0079594","time":"2026-04-20T22:52:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"좋습니다...!\n\n티아멧, d5 굴려주세요!","characters":[]},{"id":"RP-III-0079595","time":"2026-04-20T22:52:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"!1d5","characters":["P-22fdf8486544"]},{"id":"RP-III-0079596","time":"2026-04-20T22:53:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"결과 : [5]\n합계 : [5]","characters":[]},{"id":"RP-III-0079597","time":"2026-04-20T22:53:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 흠... 이건 명백한 살인이다. \"\n\n 렉시는 티아멧과 로웬을 제외한 모두를 한 번씩 훑어봅니다.\n\n\" 당신들 중 범인이 있다~ 이말이지예. \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079598","time":"2026-04-20T22:54:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"먼저, 여러분이 알 수 있는 한 가지 사실은 이 시체의 주인이 마부는 아니라는 것입니다.\n\n마부가 현재 어디로 갔는지는 알 수 없지만,\n\n여러분이 처음보는 얼굴의 사내입니다.\n\n그리고, 티아멧이 시체를 뒤집어 얼굴을 확인했을 때,\n\n무언가 가물가물한 느낌을 받습니다.\n\n이 사내를 어디선가 분명 본 적이 있습니다.\n\n그런데 잘 기억나질 않습니다.\n\n문득, 이런 생각이 듭니다. '이 마차가 처음 출발했을 때... 몇 명이었더라?'","characters":[]},{"id":"RP-III-0079599","time":"2026-04-20T22:54:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 왜 날 그렇게보지? 기분나쁜 눈이로군. \"\n\n카르도가 발끈하며 대꾸합니다.","characters":[]},{"id":"RP-III-0079600","time":"2026-04-20T22:55:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"' 어엉? 평소엔 한ㅡ 마디도 안 하다가 와 갑자기 반응하노? \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079601","time":"2026-04-20T22:55:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 니 뭐 켕기는 거 있나? \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079602","time":"2026-04-20T22:56:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 의심을 받으면 당연한 반응 아닌가? 그러는 넌 어디서 뭘했지? \"\n\n카르도가 으르렁거립니다.\n\n\" 그만! 그만 진정들 하십시다...! 우리 중 범인이 없을 수도 있지않습니까? 더군다나, 저 사체는 처음 보는 얼굴이라구요. \"\n\n로웬이 얘기합니다.","characters":[]},{"id":"RP-III-0079603","time":"2026-04-20T22:56:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"누구지, 이거...\"\n\n열심히 기억을 되짚지만, 누구였는지는 기억나지 않습니다...","characters":["P-22fdf8486544"]},{"id":"RP-III-0079604","time":"2026-04-20T22:58:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"마부는 또 어디 간 거야?\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079605","time":"2026-04-20T22:58:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 쳇 \"\n\n\" 그라모, 다들 뭐 했나 말해보지예? \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079606","time":"2026-04-20T22:58:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 가만... 드워프 어르신, 우리가 처음 마차를 타고 왔을때 몇 명이었죠? \"\n\n\" 여섯... 아니, 일곱이었나? \"\n\n\" 일곱이었어요. 아니, 여섯이었나요? \"\n\n일행들의 이야기가 엇갈립니다.\n\n우리가 처음 마차를 타고 왔을 때, 몇명이었죠?","characters":[]},{"id":"RP-III-0079607","time":"2026-04-20T22:59:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"렉시도 기억을 되짚어 봅니다","characters":["P-07a519db64cf"]},{"id":"RP-III-0079608","time":"2026-04-20T22:59:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 흐음... \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079609","time":"2026-04-20T22:59:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그 모습을 보던 카르도가 팔짱을 낀 채 마차에 기대어 얘기합니다.\n\n\" 난 너희들과 어울리는데에 이골이 나서 잠시 바람을 쐬며 걸었다. \"","characters":[]},{"id":"RP-III-0079610","time":"2026-04-20T22:59:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"뭔 소리야? 마부까지 일곱 명 아니었어?\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079611","time":"2026-04-20T22:59:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 아뇨, 마차 안에서요 티아멧씨. 마부까지 합하면... 여덟 아니었어요? \"\n\n로웬이 얘기합니다.","characters":[]},{"id":"RP-III-0079612","time":"2026-04-20T23:00:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"그렇게 많았다고?\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079613","time":"2026-04-20T23:00:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 아녜요, 티아멧님 말이 맞아요. 마부까지 일곱이었던 것 같아요. \"\n\n마이라가 얘기합니다.","characters":[]},{"id":"RP-III-0079614","time":"2026-04-20T23:00:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 와 사람이 점점 느는데예? \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079615","time":"2026-04-20T23:02:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"...저 사람이 왜 마차에 죽어 있는 걸까.\"\n\n마차와 그 주변을 살핍니다.\n시체에서 흘러나온 것을 제외하고 다른 곳에 묻어 있는 혈흔이 있나요?","characters":["P-22fdf8486544"]},{"id":"RP-III-0079616","time":"2026-04-20T23:02:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"오호, 좋습니다. 티아멧.\nd4 굴림을 해볼까요?\n\n\" 그럼 자리를 다시 확인해보세나. 각자 누가 어디에 앉았는지 설명하면서 기억을 되짚어보는게 어떤가? \"\n\n드워프 노인이 얘기합니다.","characters":[]},{"id":"RP-III-0079617","time":"2026-04-20T23:03:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"!1d4","characters":["P-22fdf8486544"]},{"id":"RP-III-0079618","time":"2026-04-20T23:03:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"결과 : [3]\n합계 : [3]","characters":[]},{"id":"RP-III-0079619","time":"2026-04-20T23:04:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"좋습니다. 티아멧이 마차와 그 주변을 살피던 도중...\n\n마차 바닥 아래로 피가 뚝 뚝 새어나오는 것이 보였습니다.\n\n여기에도 뭔가 있을까? 하며 고개를 낮춰 마차 바닥을 보니,\n\n뭔가 있습니다.\n\n이건, 희미한 마법진이 ... 그려져 있습니다...!","characters":[]},{"id":"RP-III-0079620","time":"2026-04-20T23:04:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 뭐 찾았습니꺼? \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079621","time":"2026-04-20T23:05:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 뭘 찾으셨습니까요 나으리? \"\n\n로웬도 묻습니다.","characters":[]},{"id":"RP-III-0079622","time":"2026-04-20T23:06:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"뭐야 이거. 동그라미에 이상한 게... 마법사가 그린 건가?\"\n\n피가 뚝뚝 새나오는 걸 수상하게 여겨 바닥에 누워서 마차 밑바닥을 조사하던 티아멧은 이내 희미한 마법진을 발견합니다.","characters":["P-22fdf8486544"]},{"id":"RP-III-0079623","time":"2026-04-20T23:07:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"마차 바닥에 장식용 그림을 그리진 않을 거 아냐.\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079624","time":"2026-04-20T23:07:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 마법사요? \"\n\n당신의 말에 마이라가 드워프 마법사를 쳐다봅니다.","characters":[]},{"id":"RP-III-0079625","time":"2026-04-20T23:07:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 날 왜 보시오? \"\n\n드워프 마법사가 대꾸합니다.","characters":[]},{"id":"RP-III-0079626","time":"2026-04-20T23:07:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"내도 법사긴 해","characters":["P-07a519db64cf"]},{"id":"RP-III-0079627","time":"2026-04-20T23:08:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\"... 드워프 아재, 아까 뭐 하고 계셨습니꺼? \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079628","time":"2026-04-20T23:09:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 난 ... 마차가 멈춰선 직후 잠시 앉아 그대들이 나가기를 기다렸다네. 그리고 그대들이 모두 나간 뒤 마차 안에 떨어진 물건이 없나- 살펴보곤 잠시 소변을 뉘러갔지. \"","characters":[]},{"id":"RP-III-0079629","time":"2026-04-20T23:09:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 마부도 그 즈음 마차 밖으로 나가는 것을 보았네. \"","characters":[]},{"id":"RP-III-0079630","time":"2026-04-20T23:10:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 흐음... 일단 알것습니더.. \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079631","time":"2026-04-20T23:10:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"그때, 카르도가 얘기합니다.\n\n\" 무슨 소리야? 영감은 마차 안에 있었잖아. 난 영감이 나가는 걸 본 적이 없는데? \"","characters":[]},{"id":"RP-III-0079632","time":"2026-04-20T23:11:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\".. 아니, 잠깐- 와 말이 안 맞는데예? \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079633","time":"2026-04-20T23:12:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"거짓말쟁이가 있다, 이건가?\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079634","time":"2026-04-20T23:12:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"좋습니다.\n\n여러분이 얘기한 대로, 이곳엔 진실과 거짓이 나누어진 것 같습니다.","characters":[]},{"id":"RP-III-0079635","time":"2026-04-20T23:12:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"누군가는 여러분을 속이고 있군요.","characters":[]},{"id":"RP-III-0079636","time":"2026-04-20T23:14:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 하.. 씨@불.. \"\n\n 주머니에서 담배 한 갑을 꺼내 담배 한 대를 입에 물고 불을 붙입니다.\n\n\" 이거.. 일이 길어지겠네예. \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079637","time":"2026-04-20T23:15:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 그러는 너는, 어디서 뭘 하고 있었는데? \"\n\n카르도가 티아멧을 지목합니다.","characters":[]},{"id":"RP-III-0079638","time":"2026-04-20T23:16:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"난 뭐, 지긋지긋한 마차에서 내려서, 이곳저곳 돌아다니다 방금 돌아왔어.\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079639","time":"2026-04-20T23:17:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\"... 티아멧 씨, 지금 그렇게 대충 말하면 오해 받습니더.. \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079640","time":"2026-04-20T23:17:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"렉시.\n\n티아멧이 범인이 아니라고 자부할 수 있나요?","characters":[]},{"id":"RP-III-0079641","time":"2026-04-20T23:19:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"요지는, 난 이 근방에 없었다는 거지. 마부가 어디로 갔는지도 모르고, 누가 마차에 남아있었는지도 몰라. 너희들도 나 본 적 없을걸?\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079642","time":"2026-04-20T23:20:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 흠, 그렇습니꺼.. \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079643","time":"2026-04-20T23:20:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 아무도 본 적 없다면, 그 사이 자네가 저 사내를 죽였을지 모른다는 얘기 아닌가? \"\n\n드워프 마법사가 얘기합니다.","characters":[]},{"id":"RP-III-0079644","time":"2026-04-20T23:22:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 아이, 아닐 겁니더. \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079645","time":"2026-04-20T23:22:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"내가 죽였으면, 어떻게 죽인 놈 피 하나 안 묻히고 마차에 시체를 실어 놨겠어?\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079646","time":"2026-04-20T23:24:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"잠깐의 정적.\n\n마이라가 티아멧을 쳐다보는 시선이 바뀝니다.\n\n불안에서, 공포로 말입니다.","characters":[]},{"id":"RP-III-0079647","time":"2026-04-20T23:24:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\".. 마법진이 있다는 것은.. 마법을 쓸 줄 아는 사람이 했을 수도 있는 거 아입니꺼? \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079648","time":"2026-04-20T23:26:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 그래, 게다가 저 드워프 마법사가 마차 안에 있었어. \"\n\n카르도가 얘기합니다. 그러자 드워프 마법사는 손을 가로저으며 대답합니다.\n\n\" 하지만, 티아멧양이 본 마법진은 마차 바닥에 그려져 있었잖소? 만약 내가 저 자 말대로 정말 마차 밖으로 나가지 않았다면, 어떻게 마차 바닥에 마법진을 그릴 수 있었겠습니까? \"","characters":[]},{"id":"RP-III-0079649","time":"2026-04-20T23:27:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"...일단 피해자가 누군지부터 알아내자. 저거 누군지 아는 사람 없어?\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079650","time":"2026-04-20T23:27:00+09:00","room":"RP III","name":"렉시","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 우선, 마이라 양도 들어봐야 하지 않겠습니꺼? \"","characters":["P-07a519db64cf"]},{"id":"RP-III-0079651","time":"2026-04-20T23:29:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 난... 난 마차 밖에서 잠시 한 숨을 돌리고 마차 근처에 있었어요. 왜냐하면... \"\n\n마이라가 카르도를 가르킵니다.\n\n\" 저 남자가 저를 계속 쳐다보는 느낌이 들었거든요. 그래서 마차에서 멀리 떨어지지 않은 곳에 서성거리고 있었어요... 마차엔 등불이 있으니까... 불빛이 있는 곳에선 제게 다가오지 않을까 해서요. \"\n\n그녀가 울먹입니다.\n\n그러자 카르도가 다시 으르렁거립니다.\n\n\" 완전 미친 여자 아니야 이거!? \"","characters":[]},{"id":"RP-III-0079652","time":"2026-04-20T23:32:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"...너무 경계하는 거 아냐?\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079653","time":"2026-04-20T23:33:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 하지만 ... \"\n\n마이라는 카르도의 외형에 두려움을 갖고 있는 듯 합니다.","characters":[]},{"id":"RP-III-0079654","time":"2026-04-20T23:33:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 하지만은 무슨 하지만이야, 저 게다가 시체를 처음 발견한것도 저 여자 아냐? 현장에 가장 가까이 있었던 사람이잖아. \"","characters":[]},{"id":"RP-III-0079655","time":"2026-04-20T23:36:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"아니, 잠깐, 잠깐. 사람이 죽었으면 죽은 놈이 누군지 확인해야지. 막말로 산적한테 칼 맞고 여기 기어들어와서 죽은 놈일수도 있잖아?\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079656","time":"2026-04-20T23:37:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 그래서, 마부까지 여덟이었어? 아니면 일곱이었어? \"","characters":[]},{"id":"RP-III-0079657","time":"2026-04-20T23:39:00+09:00","room":"RP III","name":"티아멧","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"내가 알기론 일곱. 지금 여기 여섯 명 있고, 마부까지 세면 일곱이잖아.\"","characters":["P-22fdf8486544"]},{"id":"RP-III-0079658","time":"2026-04-20T23:40:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"렉시는요?","characters":[]},{"id":"RP-III-0079659","time":"2026-04-20T23:42:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"@하일로 조바 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? 렉시? \n메시지가 삭제되었습니다.","characters":[]},{"id":"RP-III-0079660","time":"2026-04-20T23:46:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"렉시의... 영압이 사라졌다...!","characters":[]},{"id":"RP-III-0079661","time":"2026-04-20T23:46:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"악인이여, 특급 열차를 타라....!!","characters":[]},{"id":"RP-III-0079662","time":"2026-04-20T23:47:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"다음에 계속 ...","characters":[]},{"id":"RP-III-0079663","time":"2026-04-20T23:47:00+09:00","room":"RP III","name":"진행 / 로웬·카르도·마이라·드워프 마법사","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-III-0079664","time":"2026-04-20T23:47:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
